
function openEdit(){mask.innerHTML=`<div class="modal edit"><div class="mh">修改客户/门店<span class="close" onclick="mask.classList.remove('show')">×</span></div><div class="tabs"><span class="on" onclick="tab(0)">基本信息</span><span onclick="tab(1)">地址信息</span><span onclick="tab(2)">账期设置</span><span onclick="tab(3)">开票信息</span><span onclick="tab(4)">导入修改</span></div><div class="body"><div class="pane on"><div class="sec">基本信息</div><div class="form3"><label class="field">客户编码<input disabled value="C001"></label><label class="field"><b>*</b> 客户名称<input value="华联超市"></label><label class="field">客户类型<select><option>KA客户</option><option>流通客户</option><option>餐饮客户</option></select></label><label class="field">客户等级<select><option>金牌</option><option>银牌</option><option>普通</option></select></label><label class="field"><b>*</b> 联系人<input value="王店长"></label><label class="field"><b>*</b> 手机<input value="13888888888"></label><label class="field">片区<select><option>西湖区</option></select></label><label class="field">线路<select><option>朝阳线</option></select></label><label class="field">业务员<select><option>张三</option></select></label><label class="field">状态<select><option>正常</option><option>冻结</option><option>停用</option></select></label></div></div><div class="pane"><div class="sec">地址信息</div><table class="matrix"><tr><th>地址别名</th><th>联系人</th><th>电话</th><th>省市区</th><th>详细地址</th><th>经度</th><th>纬度</th><th>默认</th></tr><tr><td>总店</td><td>王店长</td><td>13888888888</td><td>浙江/杭州/西湖</td><td>文三路100号</td><td>120.123456</td><td>30.123456</td><td>是</td></tr></table><button class="btn primary">新增地址</button></div><div class="pane"><div class="sec">账期设置</div><div class="period-box"><div class="period-title">账期基础设置</div><div class="period-grid"><label class="switch"><input type="checkbox" checked> 是否设账期</label><label>结算方式<select id="settleType"><option>月结</option><option>固定账期</option><option>现结</option></select></label><label>信用额度<input value="50000"></label><label>账期类型<select id="periodType" onchange="periodChange()"><option value="monthlyFixed">月结固定付款日</option><option value="monthlyDays">月结账期天数</option><option value="halfMonth">半月结</option><option value="weekly">周结</option><option value="fixedDays">固定账期天数</option></select></label><label>超额控制<select><option>提醒</option><option>阻断</option><option>审批</option></select></label><label>逾期控制<select><option>提醒</option><option>禁止审核</option><option>审批放行</option></select></label></div><div class="hint">账期用于销售收货单审核后计算应收预计结款日，并影响信用额度和逾期控制。</div></div><div class="period-box" id="monthlyFixed"><div class="period-title">月结固定付款日</div><div class="period-grid"><label>截账日<input value="25"></label><label>付款月<select><option>次月</option><option>当月</option><option>隔月</option></select></label><label>付款日<input value="10"></label></div><div class="rule-preview">示例：6月1日-6月25日签收，统一在7月10日付款。</div></div><div class="period-box" id="monthlyDays" style="display:none"><div class="period-title">月结账期天数</div><div class="period-grid"><label>截账日<input value="25"></label><label>账期天数<input value="30"></label></div><div class="rule-preview">示例：6月25日截账，截账后30天为预计结款日。</div></div><div class="period-box" id="halfMonth" style="display:none"><div class="period-title">半月结</div><div class="period-grid"><label>上半月截账日<input value="15"></label><label>下半月截账日<input value="月底"></label><label>付款延后天数<input value="10"></label></div><div class="rule-preview">示例：1-15日签收为上半月账单，延后10天付款。</div></div><div class="period-box" id="weekly" style="display:none"><div class="period-title">周结</div><div class="period-grid"><label>截账星期<select><option>星期日</option><option>星期六</option></select></label><label>付款星期<select><option>星期三</option><option>星期五</option></select></label></div><div class="rule-preview">示例：每周日截账，下周三付款。</div></div><div class="period-box" id="fixedDays" style="display:none"><div class="period-title">固定账期天数</div><div class="period-grid"><label>签收后账期天数<input value="30"></label></div><div class="rule-preview">示例：客户签收后30天为预计结款日。</div></div></div><div class="pane"><div class="sec">开票信息</div><div class="form3"><label class="field">发票抬头<input value="华联超市有限公司"></label><label class="field">税号<input value="9133********"></label><label class="field">开户行<input value="工商银行"></label><label class="field">银行账号<input value="6222****"></label><label class="field">开票地址<input value="杭州市西湖区文三路100号"></label><label class="field">开票电话<input value="0571-888888"></label></div></div><div class="pane"><div class="sec">导入修改/批量修改</div><div class="period-box"><div class="period-grid"><label>导入匹配字段<select><option>客户编码</option><option>客户名称</option><option>手机号</option></select></label><label>可批量改账期<select><option>允许</option><option>不允许</option></select></label><label>失败处理<input value="下载失败原因"></label></div><div class="hint">支持批量修改客户等级、片区、线路、业务员、结算方式、账期、信用额度、状态。</div></div></div></div><div class="bottom"><button class="btn primary" onclick="toast('已保存')">保存并继续</button><button class="btn">复制新增</button><button class="btn" onclick="mask.classList.remove('show')">保存并退出</button><button class="btn" onclick="mask.classList.remove('show')">取消</button></div></div>`;mask.classList.add('show')}
function tab(i){document.querySelectorAll('.tabs span').forEach((x,n)=>x.classList.toggle('on',n==i));document.querySelectorAll('.pane').forEach((x,n)=>x.classList.toggle('on',n==i))}
function periodChange(){['monthlyFixed','monthlyDays','halfMonth','weekly','fixedDays'].forEach(id=>document.getElementById(id).style.display='none');document.getElementById(document.getElementById('periodType').value).style.display='block'}
function toast(m){let t=document.getElementById('toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2000)}
